```ts
// 纯函数：相同输入始终得到相同输出，且不修改外部状态、无副作用
function add(a: number, b: number): number {
  return a + b;
}

add(1, 2); // 3
add(1, 2); // 3
```

```ts
// 偏函数：固定一个函数的部分参数，返回一个接收剩余参数的新函数
function add(a: number, b: number, c: number) {
  return a + b + c;
}

const addFive = add.bind(null, 5);

addFive(1, 2); // 8
```

```ts
// 手写偏函数
function partial<T extends any[]>(
  fn: (...args: any[]) => any,
  ...fixedArgs: T
) {
  return (...restArgs: any[]) => fn(...fixedArgs, ...restArgs);
}

const addTen = partial(add, 5, 5);

addTen(1); // 11
```

