// 函数组合：把多个函数合并成一个函数，前一个函数的输出作为后一个函数的输入
type Fn = (arg: number) => number;

const addOne: Fn = x => x + 1;
const double: Fn = x => x * 2;
const square: Fn = x => x * x;

const composed = (...fns: Fn[]) => (x: number) =>
  fns.reduceRight((value, fn) => fn(value), x);

const fn = composed(square, double, addOne);

fn(2); // 9 => (2 + 1) * 2 = 6 => 6 * 6 = 36
```
